using UnityEngine;\nusing System.Collections;\nusing System.Collections.Generic;\n\n/// <summary>\nManages rage meter for ultimate attack charging.\n/// </summary>\npublic class RageSystem : MonoBehaviour\n{\n    [SerializeField] private float maxRage = 100f;\n    [SerializeField] private float rageGainPerHit = 5f;\n    [SerializeField] private float rageGainPerDamage = 0.1f;\n    [SerializeField] private float rageDecayRate = 5f;\n    \n    private float currentRage = 0f;\n    private float lastCombatTime = 0f;\n    \n    private void Update()\n    {\n        // Decay rage when out of combat\n        if (Time.time - lastCombatTime > 3f)\n        {\n            currentRage -= rageDecayRate * Time.deltaTime;\n            currentRage = Mathf.Max(0f, currentRage);\n        }\n    }\n    \n    public void GainRageFromAttack()\n    {\n        currentRage += rageGainPerHit;\n        currentRage = Mathf.Min(maxRage, currentRage);\n        lastCombatTime = Time.time;\n    }\n    \n    public void GainRageFromDamage(float damageReceived)\n    {\n        float rageGain = damageReceived * rageGainPerDamage;\n        currentRage += rageGain;\n        currentRage = Mathf.Min(maxRage, currentRage);\n        lastCombatTime = Time.time;\n    }\n    \n    public bool CanUseUltimate() => currentRage >= maxRage;\n    \n    public void ConsumeRage(float amount)\n    {\n        currentRage -= amount;\n        currentRage = Mathf.Max(0f, currentRage);\n    }\n    \n    public float GetRagePercent() => currentRage / maxRage;\n    public float GetCurrentRage() => currentRage;\n    public float GetMaxRage() => maxRage;\n}\n"